INSERT INTO cases VALUES ('tomato', 'early_blight', 'Tomato', 'Early blight', 'Fungal', 'A lower tomato leaf with early blight; a warm, wet week is forecast (high-risk teaching scenario).', 'Managed', 'greenhouse', 'leafspecimen.tomato.early_blight', 1.0, 'Early blight (Alternaria) causes concentric target-like spots with yellow halos, starting on older lower leaves. Spores splash from soil and debris.', 'Disease managed: lesion tissue removed, healthy tissue protected and the new leaf is clean. Old lesions remain.', 2);
INSERT INTO case_modules VALUES ('tomato', 'early_blight', 'irrigation');
