INSERT INTO steps VALUES ('grape', 'leaf_blight', 'check_old', 120, 'Recheck', 'Check the treated leaf', 'Old lesions remain|Dead tissue does not turn green', 'observe', NULL, 'lesion_spot', 1, NULL, NULL, 'old_lesions', 0, 0, 'Finding recorded.', NULL, 'Protect the healthy tissue; this lesson keeps the leaf functional.', NULL);
INSERT INTO followups VALUES ('grape', 'leaf_blight', 'new_growth', 'Inspect the new leaf', 'Functional foliage retained.', 'Continue protection after harvest where relevant.');
INSERT INTO followups VALUES ('grape', 'leaf_blight', 'old_lesions', 'Inspect the remaining lesions', 'Old lesions remain on the treated leaf; dead tissue does not recover.', 'Watch for new lesions near the old ones.');
INSERT INTO evidence VALUES ('grape', 'leaf_blight', 'Embrapa', 'https://www.infoteca.cnptia.embrapa.br/infoteca/bitstream/doc/1060452/1/ComunicadoTecnico1891.pdf', 'Reviewed for this lesson', 'Brazil', 'Studied context; susceptibility varies by cultivar.');
INSERT INTO case_profile VALUES ('tomato', 'early_blight', 'Moderate severity: about 35% of the leaf area is affected (simulated estimate).', 'Concentric, target-like brown spots|Yellow halo around each spot|Starts on older, lower leaves', 0.35, 0.7, 0.45, 0.18, 0.12, 0.6, 0.75, 0.6, 0.7, 'Dead lesion tissue does not turn green again. Good management dries the spots and stops their spread while the remaining green tissue recovers.');
INSERT INTO treatment_controls VALUES ('tomato', 'early_blight', 'sanitation', 10, 'sanitation', 'Sanitation thoroughness', 'How thoroughly affected tissue and debris are removed and disposed of (0 = nothing removed, 10 = every affected part removed and bagged).', 0, 10, 1, 2, 6, 8, 1.0, 1, 'Too little: affected tissue left in place keeps acting as an infection source.', 'More than this leaf needs: removing healthy tissue weakens the plant without extra benefit.', 'Within the recommended range. Limitation: Existing lesions on retained tissue stay.');
INSERT INTO treatment_controls VALUES ('tomato', 'early_blight', 'drip', 20, 'cultural', 'Irrigation shift to drip', '0 = all overhead watering, 10 = all water delivered at the root zone so the foliage stays dry.', 0, 10, 1, 1, 7, 10, 1.0, 1, 'Overhead watering keeps leaves wet and splashes the pathogen onto healthy tissue.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: Does not remove existing infection.');
INSERT INTO treatment_controls VALUES ('tomato', 'early_blight', 'protect', 30, 'protect', 'Protective spray coverage', 'Share of the healthy tissue covered with a suitable, labelled protectant category. Abstract 0-10 scale: no product or dose is taught.', 0, 10, 1, 1, 5, 7, 0.8, 1, 'Too little coverage leaves healthy tissue exposed while conditions favour infection.', 'Over-application adds cost, residue and resistance risk without extra protection.', 'Within the recommended range. Limitation: Does not cure lesions; product and dose follow the local label.');
INSERT INTO treatment_controls VALUES ('tomato', 'early_blight', 'prevention', 40, 'future', 'Prevention planning', 'Rotation, residue management, resistant varieties and clean stock for later crops.', 0, 10, 1, 0, 5, 10, 0.4, 0, 'Without planning, the next crop starts with the same risk.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: Not an immediate treatment.');
INSERT INTO control_rules VALUES ('tomato', 'early_blight', 'wet_spray', 'drip', 0, 3, 'protect', 5, 10, 0.25, 0, 'Spraying while overhead watering keeps the foliage wet: the coating washes off and splash keeps spreading the disease.');
INSERT INTO case_profile VALUES ('tomato', 'bacterial_spot', 'Moderate severity: about 30% of the leaf area is affected (simulated estimate).', 'Small, dark, water-soaked spots|Spots visible on both leaf surfaces|Spread by splash, hands and tools', 0.3, 0.74, 0.45, 0.16, 0.12, 0.6, 0.75, 0.6, 0.7, 'Dead lesion tissue does not turn green again. Good management dries the spots and stops their spread while the remaining green tissue recovers.');
INSERT INTO treatment_controls VALUES ('tomato', 'bacterial_spot', 'sanitation', 10, 'hygiene', 'Hygiene and selective removal', 'How thoroughly affected tissue and debris are removed and disposed of (0 = nothing removed, 10 = every affected part removed and bagged).', 0, 10, 1, 2, 6, 8, 1.0, 1, 'Too little: affected tissue left in place keeps acting as an infection source.', 'More than this leaf needs: removing healthy tissue weakens the plant without extra benefit.', 'Within the recommended range. Limitation: Established infection is managed, not cured.');
INSERT INTO treatment_controls VALUES ('tomato', 'bacterial_spot', 'drip', 20, 'irrigation', 'Irrigation shift to drip', '0 = all overhead watering, 10 = all water delivered at the root zone so the foliage stays dry.', 0, 10, 1, 1, 8, 10, 1.2, 1, 'Overhead watering keeps leaves wet and splashes the pathogen onto healthy tissue.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: Does not remove existing infection.');
INSERT INTO treatment_controls VALUES ('tomato', 'bacterial_spot', 'protect', 30, 'copper', 'Copper protection coverage (supplement)', 'Share of the healthy tissue covered with a suitable, labelled protectant category. Abstract 0-10 scale: no product or dose is taught.', 0, 10, 1, 0, 3, 5, 0.5, 1, 'Too little coverage leaves healthy tissue exposed while conditions favour infection.', 'Over-application adds cost, residue and resistance risk without extra protection.', 'Within the recommended range. Limitation: Limited efficacy; copper resistance is documented.');
INSERT INTO control_rules VALUES ('tomato', 'bacterial_spot', 'overhead', 'drip', 0, 2, NULL, NULL, NULL, 0.25, 0, 'Heavy overhead irrigation splashes bacteria from leaf to leaf.');
INSERT INTO case_profile VALUES ('tomato', 'late_blight', 'Severe severity: about 60% of the leaf area is affected (simulated estimate).', 'Large, greasy grey-green lesions|White growth at lesion edges in humid air|Lesions expand quickly', 0.6, 0.49, 0.0, 0.0, 0.15, 0.0, 0.0, 0.0, 0.0, 'This leaf cannot be saved by treatment. Correct containment stops it acting as a source; recovery means replacing it with clean stock.');
INSERT INTO treatment_controls VALUES ('tomato', 'late_blight', 'containment', 10, 'contain', 'Containment', 'Bagging, isolating and removing infected material so it cannot act as a source.', 0, 10, 1, 2, 9, 10, 1.5, 1, 'Infected material that is not contained keeps spreading the disease.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: Infected material cannot be saved.');
INSERT INTO treatment_controls VALUES ('tomato', 'late_blight', 'protect', 20, 'protect', 'Neighbour protection coverage', 'Coverage of healthy neighbouring hosts with a late-blight-active protectant category. Abstract scale: no product or dose is taught.', 0, 10, 1, 1, 6, 8, 1.0, 1, 'Too little coverage leaves healthy tissue exposed while conditions favour infection.', 'Over-application adds cost, residue and resistance risk without extra protection.', 'Within the recommended range. Limitation: Ordinary fungicides cannot be assumed effective against a water mould.');
INSERT INTO treatment_controls VALUES ('tomato', 'late_blight', 'replacement', 30, 'clean_stock', 'Clean replacement stock', 'Readiness to replace infected plants with certified clean, suitable stock.', 0, 10, 1, 1, 7, 10, 1.0, 1, 'Without clean replacement stock the space is replanted with risky material or stays empty.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: Windborne spores can still arrive.');
INSERT INTO control_rules VALUES ('tomato', 'late_blight', 'not_contained', 'containment', 0, 6, NULL, NULL, NULL, 0.5, 1, 'Late blight spreads fast: without full containment the outbreak continues. The infected leaf cannot be saved.');
INSERT INTO case_profile VALUES ('tomato', 'leaf_mold', 'Moderate severity: about 35% of the leaf area is affected (simulated estimate).', 'Pale yellow patches on the upper surface|Olive-brown velvety mould underneath|Favoured by prolonged high humidity', 0.35, 0.7, 0.45, 0.18, 0.12, 0.6, 0.75, 0.6, 0.7, 'Dead lesion tissue does not turn green again. Good management dries the spots and stops their spread while the remaining green tissue recovers.');
INSERT INTO treatment_controls VALUES ('tomato', 'leaf_mold', 'airflow', 10, 'environment', 'Ventilation / airflow', 'Venting, spacing and air circulation that shorten leaf-wetness periods.', 0, 10, 1, 1, 7, 9, 1.3, 1, 'Still, humid air keeps leaves wet long enough for new infections.', 'Excess airflow chills and dries the crop without extra disease benefit.', 'Within the recommended range. Limitation: Must be maintained.');
INSERT INTO treatment_controls VALUES ('tomato', 'leaf_mold', 'sanitation', 20, 'sanitation', 'Sanitation thoroughness', 'How thoroughly affected tissue and debris are removed and disposed of (0 = nothing removed, 10 = every affected part removed and bagged).', 0, 10, 1, 1, 5, 7, 1.0, 1, 'Too little: affected tissue left in place keeps acting as an infection source.', 'More than this leaf needs: removing healthy tissue weakens the plant without extra benefit.', 'Within the recommended range. Limitation: Old patches remain.');
INSERT INTO treatment_controls VALUES ('tomato', 'leaf_mold', 'protect', 30, 'protect', 'Protective spray coverage (supplement)', 'Share of the healthy tissue covered with a suitable, labelled protectant category. Abstract 0-10 scale: no product or dose is taught.', 0, 10, 1, 0, 3, 5, 0.5, 1, 'Too little coverage leaves healthy tissue exposed while conditions favour infection.', 'Over-application adds cost, residue and resistance risk without extra protection.', 'Within the recommended range. Limitation: Supplements, not replaces, environmental control.');
INSERT INTO control_rules VALUES ('tomato', 'leaf_mold', 'closed_vents', 'airflow', 0, 3, 'protect', 4, 10, 0.3, 0, 'Spraying with the vents closed will not hold leaf mold back.');
INSERT INTO case_profile VALUES ('tomato', 'septoria_leaf_spot', 'Moderate severity: about 40% of the leaf area is affected (simulated estimate).', 'Many small circular spots with pale centres|Tiny dark fruiting bodies (pycnidia)|Spreads upward from lower leaves', 0.4, 0.66, 0.45, 0.2, 0.12, 0.6, 0.75, 0.6, 0.7, 'Dead lesion tissue does not turn green again. Good management dries the spots and stops their spread while the remaining green tissue recovers.');
INSERT INTO treatment_controls VALUES ('tomato', 'septoria_leaf_spot', 'sanitation', 10, 'sanitation', 'Sanitation thoroughness', 'How thoroughly affected tissue and debris are removed and disposed of (0 = nothing removed, 10 = every affected part removed and bagged).', 0, 10, 1, 2, 6, 8, 1.0, 1, 'Too little: affected tissue left in place keeps acting as an infection source.', 'More than this leaf needs: removing healthy tissue weakens the plant without extra benefit.', 'Within the recommended range. Limitation: Retained tissue keeps its spots.');
INSERT INTO treatment_controls VALUES ('tomato', 'septoria_leaf_spot', 'drip', 20, 'cultural', 'Irrigation shift to drip', '0 = all overhead watering, 10 = all water delivered at the root zone so the foliage stays dry.', 0, 10, 1, 1, 7, 10, 1.0, 1, 'Overhead watering keeps leaves wet and splashes the pathogen onto healthy tissue.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: Prevention, not cure.');
INSERT INTO treatment_controls VALUES ('tomato', 'septoria_leaf_spot', 'protect', 30, 'protect', 'Protective spray coverage', 'Share of the healthy tissue covered with a suitable, labelled protectant category. Abstract 0-10 scale: no product or dose is taught.', 0, 10, 1, 1, 4, 6, 0.7, 1, 'Too little coverage leaves healthy tissue exposed while conditions favour infection.', 'Over-application adds cost, residue and resistance risk without extra protection.', 'Within the recommended range. Limitation: Does not remove existing spots.');
INSERT INTO control_rules VALUES ('tomato', 'septoria_leaf_spot', 'wet_spray', 'drip', 0, 3, 'protect', 5, 10, 0.25, 0, 'Spraying while overhead watering keeps the foliage wet: the coating washes off and splash keeps spreading the disease.');
INSERT INTO case_profile VALUES ('tomato', 'spider_mites', 'Moderate severity: about 30% of the leaf area is affected (simulated estimate).', 'Pale stippling on the upper surface|Fine webbing and moving mites underneath|Worse on hot, dry, water-stressed plants', 0.3, 0.74, 0.3, 0.15, 0.12, 0.35, 0.4, 0.35, 0.4, 'Old stippling stays. Fewer active mites means the speckling stops spreading and later growth is cleaner.');
INSERT INTO treatment_controls VALUES ('tomato', 'spider_mites', 'stress', 10, 'conditions', 'Plant stress relief', 'Correct watering and nutrition so the plant is less stressed.', 0, 10, 1, 2, 6, 8, 1.0, 1, 'A stressed plant stays more susceptible.', 'Over-watering stresses roots and favours other problems.', 'Within the recommended range. Limitation: Does not remove a colony alone.');
INSERT INTO treatment_controls VALUES ('tomato', 'spider_mites', 'biocontrol', 20, 'biological', 'Biological control', 'Release and conservation of natural enemies such as predatory mites.', 0, 10, 1, 1, 6, 8, 1.0, 1, 'Too few natural enemies to hold the colony back.', 'More predators than the colony can support; most starve or disperse.', 'Within the recommended range. Limitation: Needs time and compatible treatments.');
INSERT INTO treatment_controls VALUES ('tomato', 'spider_mites', 'contact', 30, 'contact', 'Directed contact treatment', 'Directed water wash and a labelled contact treatment on the colonies. Abstract 0-10 scale: no product or dose is taught.', 0, 10, 1, 0, 3, 5, 0.7, 1, 'Too little contact treatment leaves the colony active.', 'Repeated heavy contact treatment harms natural enemies and stresses the leaf.', 'Within the recommended range. Limitation: Contact only; repeat checks needed.');
INSERT INTO control_rules VALUES ('tomato', 'spider_mites', 'kills_predators', 'biocontrol', 6, 10, 'contact', 7, 10, 0.3, 0, 'Heavy contact treatment right after a predator release kills the predators.');
INSERT INTO case_profile VALUES ('tomato', 'target_spot', 'Moderate severity: about 40% of the leaf area is affected (simulated estimate).', 'Brown spots with concentric rings|Inner-canopy leaves first|Favoured by long leaf wetness', 0.4, 0.66, 0.45, 0.2, 0.12, 0.6, 0.75, 0.6, 0.7, 'Dead lesion tissue does not turn green again. Good management dries the spots and stops their spread while the remaining green tissue recovers.');
INSERT INTO treatment_controls VALUES ('tomato', 'target_spot', 'sanitation', 10, 'sanitation', 'Sanitation thoroughness', 'How thoroughly affected tissue and debris are removed and disposed of (0 = nothing removed, 10 = every affected part removed and bagged).', 0, 10, 1, 2, 6, 8, 1.0, 1, 'Too little: affected tissue left in place keeps acting as an infection source.', 'More than this leaf needs: removing healthy tissue weakens the plant without extra benefit.', 'Within the recommended range. Limitation: Advanced damage remains.');
INSERT INTO treatment_controls VALUES ('tomato', 'target_spot', 'airflow', 20, 'drying', 'Ventilation / airflow', 'Venting, spacing and air circulation that shorten leaf-wetness periods.', 0, 10, 1, 1, 7, 9, 1.0, 1, 'Still, humid air keeps leaves wet long enough for new infections.', 'Excess airflow chills and dries the crop without extra disease benefit.', 'Within the recommended range. Limitation: Must be maintained.');
INSERT INTO treatment_controls VALUES ('tomato', 'target_spot', 'protect', 30, 'programme', 'Protective programme coverage', 'Coverage with an effective protectant programme that rotates modes of action. Abstract scale: no product or dose is taught.', 0, 10, 1, 1, 6, 8, 1.0, 1, 'Too little coverage leaves healthy tissue exposed while conditions favour infection.', 'Over-application adds cost, residue and resistance risk without extra protection.', 'Within the recommended range. Limitation: Do not assume an early-blight claim applies.');
INSERT INTO control_rules VALUES ('tomato', 'target_spot', 'wet_canopy', 'airflow', 0, 3, 'protect', 6, 10, 0.2, 0, 'Long leaf wetness undermines any protectant programme.');
INSERT INTO case_profile VALUES ('tomato', 'yellow_leaf_curl_virus', 'Severe severity: about 55% of the leaf area is affected (simulated estimate).', 'Upward-curled, yellowed young leaves|Stunted new growth|Whiteflies on the underside', 0.55, 0.53, 0.0, 0.0, 0.15, 0.0, 0.0, 0.0, 0.0, 'This leaf cannot be saved by treatment. Correct containment stops it acting as a source; recovery means replacing it with clean stock.');
INSERT INTO treatment_controls VALUES ('tomato', 'yellow_leaf_curl_virus', 'containment', 10, 'contain', 'Containment', 'Bagging, isolating and removing infected material so it cannot act as a source.', 0, 10, 1, 2, 9, 10, 1.5, 1, 'Infected material that is not contained keeps spreading the disease.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: Infected tissue is not cured.');
INSERT INTO treatment_controls VALUES ('tomato', 'yellow_leaf_curl_virus', 'vector', 20, 'vectors', 'Vector control', 'Exclusion mesh and monitoring cards that keep insect vectors away from clean plants.', 0, 10, 1, 1, 7, 10, 1.2, 1, 'Vectors left unmanaged carry the virus to healthy plants.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: Requires continued monitoring.');
INSERT INTO treatment_controls VALUES ('tomato', 'yellow_leaf_curl_virus', 'replacement', 30, 'clean_stock', 'Clean replacement stock', 'Readiness to replace infected plants with certified clean, suitable stock.', 0, 10, 1, 1, 7, 10, 1.0, 1, 'Without clean replacement stock the space is replanted with risky material or stays empty.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: Resistance may not eliminate symptoms.');
INSERT INTO control_rules VALUES ('tomato', 'yellow_leaf_curl_virus', 'not_contained', 'containment', 0, 6, NULL, NULL, NULL, 0.5, 1, 'There is no cure: an infected plant that is not contained stays a virus source.');
INSERT INTO control_rules VALUES ('tomato', 'yellow_leaf_curl_virus', 'open_vectors', 'vector', 0, 3, NULL, NULL, NULL, 0.3, 0, 'Whiteflies left unmanaged carry the virus to the replacement.');
