INSERT INTO treatment_controls VALUES ('tomato', 'mosaic_virus', 'sanitation', 20, 'sanitation', 'Hygiene of hands, tools and surfaces', 'Validated cleaning of hands, tools, supports and work surfaces after handling infected material.', 0, 10, 1, 2, 8, 10, 1.2, 1, 'Too little: affected tissue left in place keeps acting as an infection source.', 'More than this leaf needs: removing healthy tissue weakens the plant without extra benefit.', 'Within the recommended range. Limitation: Must follow validated procedures.');
INSERT INTO treatment_controls VALUES ('tomato', 'mosaic_virus', 'replacement', 30, 'clean_stock', 'Clean replacement stock', 'Readiness to replace infected plants with certified clean, suitable stock.', 0, 10, 1, 1, 7, 10, 1.0, 1, 'Without clean replacement stock the space is replanted with risky material or stays empty.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: Resistance varies by strain.');
INSERT INTO control_rules VALUES ('tomato', 'mosaic_virus', 'not_contained', 'containment', 0, 6, NULL, NULL, NULL, 0.5, 1, 'Mosaic virus has no cure: infected material that stays in place keeps spreading mechanically.');
INSERT INTO control_rules VALUES ('tomato', 'mosaic_virus', 'dirty_replant', 'sanitation', 0, 4, 'replacement', 7, 10, 0.35, 0, 'Planting clean stock with unsanitised hands and tools re-infects it.');
