INSERT INTO treatment_controls VALUES ('cherry', 'powdery_mildew', 'protect', 20, 'protect', 'Mildew treatment coverage', 'Coverage with a cherry-labelled mildew treatment category suited to stage and temperature. Abstract scale: no product or dose is taught.', 0, 10, 1, 1, 6, 8, 1.0, 1, 'Too little coverage leaves healthy tissue exposed while conditions favour infection.', 'Over-application adds cost, residue and resistance risk without extra protection.', 'Within the recommended range. Limitation: Depends on growth stage, temperature and compatibility.');
