INSERT INTO treatment_controls VALUES ('peach', 'bacterial_spot', 'stress', 10, 'cultural', 'Tree stress relief (water, nutrition)', 'Correct watering and nutrition so the plant is less stressed.', 0, 10, 1, 2, 7, 9, 1.2, 1, 'A stressed plant stays more susceptible.', 'Over-watering stresses roots and favours other problems.', 'Within the recommended range. Limitation: Gradual.');
INSERT INTO treatment_controls VALUES ('peach', 'bacterial_spot', 'monitoring', 20, 'copper', 'Treatment-window records', 'Recording the next label-permitted treatment stage instead of spraying copper on summer foliage.', 0, 10, 1, 1, 6, 8, 1.0, 1, 'Without regular checks, new symptoms are found too late.', 'More frequent checks than needed cost time without changing decisions.', 'Within the recommended range. Limitation: Leaf injury and label limits apply.');
INSERT INTO treatment_controls VALUES ('peach', 'bacterial_spot', 'prevention', 30, 'resistance', 'Resistant variety planning', 'Rotation, residue management, resistant varieties and clean stock for later crops.', 0, 10, 1, 0, 6, 10, 0.6, 1, 'Without planning, the next crop starts with the same risk.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: For future planting.');
INSERT INTO case_profile VALUES ('bell_pepper', 'bacterial_spot', 'Moderate severity: about 30% of the leaf area is affected (simulated estimate).', 'Small dark leaf spots|Spots visible underneath|Spotted transplants in the new tray', 0.3, 0.74, 0.45, 0.16, 0.12, 0.6, 0.75, 0.6, 0.7, 'Dead lesion tissue does not turn green again. Good management dries the spots and stops their spread while the remaining green tissue recovers.');
INSERT INTO treatment_controls VALUES ('bell_pepper', 'bacterial_spot', 'replacement', 10, 'clean_stock', 'Clean seed and transplants', 'Rejecting spotted transplants and using clean seed and stock.', 0, 10, 1, 2, 8, 10, 1.0, 1, 'Without clean replacement stock the space is replanted with risky material or stays empty.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: Does not cure infected plants.');
INSERT INTO treatment_controls VALUES ('bell_pepper', 'bacterial_spot', 'sanitation', 20, 'hygiene', 'Hygiene and selective removal', 'How thoroughly affected tissue and debris are removed and disposed of (0 = nothing removed, 10 = every affected part removed and bagged).', 0, 10, 1, 2, 6, 8, 1.0, 1, 'Too little: affected tissue left in place keeps acting as an infection source.', 'More than this leaf needs: removing healthy tissue weakens the plant without extra benefit.', 'Within the recommended range. Limitation: Managed, not cured.');
INSERT INTO treatment_controls VALUES ('bell_pepper', 'bacterial_spot', 'protect', 30, 'copper', 'Copper protection coverage (supplement)', 'Share of the healthy tissue covered with a suitable, labelled protectant category. Abstract 0-10 scale: no product or dose is taught.', 0, 10, 1, 0, 3, 5, 0.5, 1, 'Too little coverage leaves healthy tissue exposed while conditions favour infection.', 'Over-application adds cost, residue and resistance risk without extra protection.', 'Within the recommended range. Limitation: Resistance documented.');
INSERT INTO case_profile VALUES ('strawberry', 'leaf_scorch', 'Moderate severity: about 40% of the leaf area is affected (simulated estimate).', 'Small purple spots|Spots merge until the leaf looks scorched|Survives on old leaves', 0.4, 0.66, 0.45, 0.2, 0.12, 0.6, 0.75, 0.6, 0.7, 'Dead lesion tissue does not turn green again. Good management dries the spots and stops their spread while the remaining green tissue recovers.');
INSERT INTO treatment_controls VALUES ('strawberry', 'leaf_scorch', 'drip', 10, 'water', 'Irrigation shift to drip', '0 = all overhead watering, 10 = all water delivered at the root zone so the foliage stays dry.', 0, 10, 1, 1, 7, 10, 1.0, 1, 'Overhead watering keeps leaves wet and splashes the pathogen onto healthy tissue.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: Ongoing.');
INSERT INTO treatment_controls VALUES ('strawberry', 'leaf_scorch', 'sanitation', 20, 'renovation', 'Renovation thoroughness', 'Removal of old foliage at post-harvest renovation without damaging the crowns.', 0, 10, 1, 1, 6, 8, 1.0, 1, 'Too little: affected tissue left in place keeps acting as an infection source.', 'More than this leaf needs: removing healthy tissue weakens the plant without extra benefit.', 'Within the recommended range. Limitation: Timing matters; never damage crowns.');
