INSERT INTO case_profile VALUES ('potato', 'early_blight', 'Moderate severity: about 35% of the leaf area is affected (simulated estimate).', 'Dark concentric lesions|Older leaves first|Worse on water-stressed plants', 0.35, 0.7, 0.45, 0.18, 0.12, 0.6, 0.75, 0.6, 0.7, 'Dead lesion tissue does not turn green again. Good management dries the spots and stops their spread while the remaining green tissue recovers.');
INSERT INTO treatment_controls VALUES ('potato', 'early_blight', 'stress', 10, 'care', 'Irrigation and nutrition (stress relief)', 'Correct watering and nutrition so the plant is less stressed.', 0, 10, 1, 2, 6, 8, 1.0, 1, 'A stressed plant stays more susceptible.', 'Over-watering stresses roots and favours other problems.', 'Within the recommended range. Limitation: Gradual.');
INSERT INTO treatment_controls VALUES ('potato', 'early_blight', 'protect', 20, 'protect', 'Protective spray coverage', 'Share of the healthy tissue covered with a suitable, labelled protectant category. Abstract 0-10 scale: no product or dose is taught.', 0, 10, 1, 1, 5, 7, 1.0, 1, 'Too little coverage leaves healthy tissue exposed while conditions favour infection.', 'Over-application adds cost, residue and resistance risk without extra protection.', 'Within the recommended range. Limitation: Old lesions remain.');
INSERT INTO treatment_controls VALUES ('potato', 'early_blight', 'prevention', 30, 'clean', 'Clean seed, rotation and volunteer control', 'Rotation, residue management, resistant varieties and clean stock for later crops.', 0, 10, 1, 1, 6, 10, 0.6, 0, 'Without planning, the next crop starts with the same risk.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: Long-term.');
INSERT INTO case_profile VALUES ('potato', 'late_blight', 'Severe severity: about 60% of the leaf area is affected (simulated estimate).', 'Water-soaked, expanding lesions|White growth underneath in humid air|Reddish-brown rot in tubers', 0.6, 0.49, 0.0, 0.0, 0.15, 0.0, 0.0, 0.0, 0.0, 'This leaf cannot be saved by treatment. Correct containment stops it acting as a source; recovery means replacing it with clean stock.');
INSERT INTO treatment_controls VALUES ('potato', 'late_blight', 'containment', 10, 'contain', 'Containment', 'Bagging, isolating and removing infected material so it cannot act as a source.', 0, 10, 1, 2, 9, 10, 1.5, 1, 'Infected material that is not contained keeps spreading the disease.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: Infected material is not saved.');
INSERT INTO treatment_controls VALUES ('potato', 'late_blight', 'protect', 20, 'protect', 'Neighbour protection coverage', 'Coverage of healthy neighbouring hosts with a late-blight-active protectant category. Abstract scale: no product or dose is taught.', 0, 10, 1, 1, 6, 8, 1.0, 1, 'Too little coverage leaves healthy tissue exposed while conditions favour infection.', 'Over-application adds cost, residue and resistance risk without extra protection.', 'Within the recommended range. Limitation: Ordinary fungicides cannot be assumed effective.');
INSERT INTO treatment_controls VALUES ('potato', 'late_blight', 'replacement', 30, 'clean_seed', 'Certified seed for the later crop', 'Readiness to replace infected plants with certified clean, suitable stock.', 0, 10, 1, 1, 7, 10, 1.0, 1, 'Without clean replacement stock the space is replanted with risky material or stays empty.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: Windborne spores can still arrive.');
INSERT INTO control_rules VALUES ('potato', 'late_blight', 'not_contained', 'containment', 0, 6, NULL, NULL, NULL, 0.5, 1, 'Late blight spreads fast: without full containment of foliage and tubers the outbreak continues.');
