INSERT INTO treatment_controls VALUES ('grape', 'black_rot', 'sanitation', 10, 'sanitation', 'Sanitation thoroughness (mummies)', 'How thoroughly affected tissue and debris are removed and disposed of (0 = nothing removed, 10 = every affected part removed and bagged).', 0, 10, 1, 2, 8, 10, 1.3, 1, 'Too little: affected tissue left in place keeps acting as an infection source.', 'More than this leaf needs: removing healthy tissue weakens the plant without extra benefit.', 'Within the recommended range. Limitation: Must include ground mummies.');
INSERT INTO treatment_controls VALUES ('grape', 'black_rot', 'airflow', 20, 'drying', 'Canopy drying / airflow', 'Venting, spacing and air circulation that shorten leaf-wetness periods.', 0, 10, 1, 1, 6, 8, 1.0, 1, 'Still, humid air keeps leaves wet long enough for new infections.', 'Excess airflow chills and dries the crop without extra disease benefit.', 'Within the recommended range. Limitation: Ongoing.');
INSERT INTO treatment_controls VALUES ('grape', 'black_rot', 'protect', 30, 'protect', 'Protective spray coverage', 'Share of the healthy tissue covered with a suitable, labelled protectant category. Abstract 0-10 scale: no product or dose is taught.', 0, 10, 1, 1, 5, 7, 1.0, 1, 'Too little coverage leaves healthy tissue exposed while conditions favour infection.', 'Over-application adds cost, residue and resistance risk without extra protection.', 'Within the recommended range. Limitation: Infected berries are not saved.');
INSERT INTO control_rules VALUES ('grape', 'black_rot', 'mummies_left', 'sanitation', 0, 4, 'protect', 5, 10, 0.25, 0, 'Spraying while berry mummies stay on the vine leaves the main infection source in place.');
