INSERT INTO treatment_controls VALUES ('grape', 'esca', 'containment', 10, 'replace', 'Containment and removal of the vine', 'Isolating and removing the severely affected vine (assisted removal in the field).', 0, 10, 1, 2, 9, 10, 1.5, 1, 'Infected material that is not contained keeps spreading the disease.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: The original vine is not cured.');
INSERT INTO treatment_controls VALUES ('grape', 'esca', 'replacement', 20, 'replace', 'Clean replacement vine', 'Readiness to replace infected plants with certified clean, suitable stock.', 0, 10, 1, 1, 7, 10, 1.0, 1, 'Without clean replacement stock the space is replanted with risky material or stays empty.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: The original vine is not cured.');
