INSERT INTO control_rules VALUES ('grape', 'esca', 'not_contained', 'containment', 0, 6, NULL, NULL, NULL, 0.5, 1, 'Esca lives in the wood: leaving the severely affected vine in place keeps the source. No foliar treatment cures it.');
